def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    environment = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def get_closest_target(targets):
        if not targets:
            return None
        return min(targets, key=lambda pos: abs(pos[0] - sx) + abs(pos[1] - sy))

    def move_towards(target):
        dx, dy = 0, 0
        if target:
            if target[0] > sx:
                dx = 1
            elif target[0] < sx:
                dx = -1
            if target[1] > sy:
                dy = 1
            elif target[1] < sy:
                dy = -1
        else:
            dx, dy = 0, 0
        # Add a small randomness to avoid deterministic loops
        # since no imports are allowed, just randomly choose directions based on positions.
        return dx, dy

    # Defensive default (center or random direction)
    def fallback_move():
        # Choose a direction that tends to keep you within grid
        dx = 0
        dy = 0
        if sx > grid_width // 2:
            dx = -1
        elif sx < grid_width // 2:
            dx = 1
        if sy > grid_height // 2:
            dy = -1
        elif sy < grid_height // 2:
            dy = 1
        return dx, dy

    # Behavior based on environment
    if environment == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = get_closest_target([observation.get("resources", []), observation.get("opponent_position", (0, 0))])
            if target:
                return list(move_towards(target))
            else:
                return list(fallback_move())
        else:
            # Evader: move away from opponent
            # Simple heuristic: move opposite to opponent
            dx = 0
            dy = 0
            if ox > sx:
                dx = -1
            elif ox < sx:
                dx = 1
            if oy > sy:
                dy = -1
            elif oy < sy:
                dy = 1
            return [dx, dy]

    elif environment == "territory_control":
        unclaimed = observation.get("unclaimed_cells") or []
        terrains = unclaimed or observation.get("opponent_territory") or []
        target = get_closest_target(terrains)
        if target:
            return list(move_towards(target))
        else:
            return list(fallback_move())

    else:
        # resource_collection or default
        resources = observation.get("resources") or []
        target = get_closest_target(resources)
        if target:
            return list(move_towards(target))
        else:
            # No resources, move towards center
            return list(fallback_move())

